// CPIA - Clinical Protocol Intelligence Assistant
// Input Guardrail: Blacklist Check
// Demo Version 1.0

const inputItems = $input.all();

// Patterns targeting attempts to override CPIA instructions.
// Medical questions are not blocked merely for mentioning
// words such as insulin, DKA, protocols, or treatment.

const blacklist = [
  {
    id: "IGNORE_INSTRUCTIONS",
    pattern: /\b(ignore|disregard|forget|bypass)\s+(all\s+)?(previous|prior|above|system|developer|safety)\s+(instructions?|rules?|prompts?|restrictions?)\b/i
  },
  {
    id: "REVEAL_INTERNAL_PROMPT",
    pattern: /\b(reveal|show|print|disclose|leak)\s+(me\s+)?(your\s+)?(hidden|internal|system|developer)\s+(prompt|instructions?|rules?)\b/i
  },
  {
    id: "OVERRIDE_SAFETY",
    pattern: /\b(disable|remove|turn off|override|bypass)\s+(your\s+|the\s+)?(safety|guardrails?|restrictions?|security checks?)\b/i
  },
  {
    id: "FABRICATE_EVIDENCE",
    pattern: /\b(fabricate|invent|fake|make up)\s+(a\s+|the\s+)?(medical\s+|clinical\s+)?(citations?|references?|sources?|evidence)\b/i
  },
  {
    id: "ARABIC_IGNORE",
    pattern: /(?:تجاهل|تخطى|تجاوز|انسى|انسَ)\s+(?:كل\s+)?(?:التعليمات|الأوامر|القواعد|القيود)\s*(?:السابقة|الداخلية|الأساسية|النظام)?/i
  },
  {
    id: "ARABIC_REVEAL",
    pattern: /(?:اكشف|اظهر|أظهر|اعرض)\s+(?:لي\s+)?(?:تعليماتك|التعليمات الداخلية|برومبت النظام|رسالة النظام)/i
  },
  {
    id: "ARABIC_FAKE_SOURCES",
    pattern: /(?:اختلق|اخترع|زيف|زوّر)\s+(?:لي\s+)?(?:مراجع|مصادر|استشهادات|أدلة)/i
  }
];

return inputItems.map((item, index) => {

  const userMessage =
  typeof item.json.userMessage === "string"
    ? item.json.userMessage.trim()
    : "";

  const sessionId = item.json.sessionId ?? null;

  const normalizedText = userMessage
    .normalize("NFKC")
    .replace(/[\u200B-\u200D\uFEFF]/g, "")
    .replace(/\s+/g, " ");

  // Avoid blocking educational questions that discuss
  // prompt injection as a concept.
  const educationalContext =
    /\b(what is|explain|define|example of|how to detect|how to prevent)\b/i.test(normalizedText) ||
    /(?:ما معنى|ما هو|اشرح|فسر|مثال على|كيفية اكتشاف|كيفية منع)/i.test(normalizedText);

  const match = blacklist.find(rule =>
    rule.pattern.test(normalizedText)
  );

  const blacklistHit = Boolean(match) && !educationalContext;

  const emptyInput = normalizedText.length === 0;

  const tooLong = normalizedText.length > 4000;

  const blocked = blacklistHit || emptyInput || tooLong;

  let blockReason = null;

  if (emptyInput) {
    blockReason = "EMPTY_INPUT";
  } else if (tooLong) {
    blockReason = "INPUT_TOO_LONG";
  } else if (blacklistHit) {
    blockReason = match.id;
  }

  return {
    json: {
      userMessage,
      sessionId,

      blacklistHit: blocked,
      blacklistMatch: blockReason,

      inputStatus: blocked ? "BLOCK" : "ALLOW",

      guardrailStage: "INPUT_BLACKLIST",
      project: "CPIA",
      environment: "demo_only"
    },
    pairedItem: {
      item: index
    }
  };

});

const llmOutput = String($json.text ?? "");
const userMessage =
  $('Blacklist Check').item.json.userMessage;

const sessionId =
  $('Blacklist Check').item.json.sessionId;

// 1. Existing safety checks
const canaryLeaked = llmOutput.includes("CANARY-REPLACE_FOR_PRIVATE_DEPLOYMENT");
const empty = llmOutput.trim().length === 0;
const tooLong = llmOutput.length > 4000;

// 2. Parse LLM decision
let verdict = null;

try {
  const cleaned = llmOutput
    .replace(/```json/gi, "")
    .replace(/```/g, "")
    .trim();

  verdict = JSON.parse(cleaned);
} catch (error) {
  verdict = null;
}

// 3. Validate JSON structure
const validStructure =
  verdict !== null &&
  typeof verdict === "object" &&
  !Array.isArray(verdict) &&
  ["ALLOW", "BLOCK"].includes(verdict.decision) &&
  ["LOW", "MEDIUM", "HIGH"].includes(verdict.risk_level) &&
  typeof verdict.reason_code === "string" &&
  verdict.reason_code.trim().length > 0 &&
  typeof verdict.explanation === "string";

// 4. Final validation
const validationFailed =
  canaryLeaked ||
  empty ||
  tooLong ||
  !validStructure ||
  verdict.decision !== "ALLOW";

// 5. Determine reason
let validationReason = null;

if (canaryLeaked) {
  validationReason = "CANARY_LEAK";
} else if (empty) {
  validationReason = "EMPTY_OUTPUT";
} else if (tooLong) {
  validationReason = "OUTPUT_TOO_LONG";
} else if (!validStructure) {
  validationReason = "INVALID_JSON";
} else if (verdict.decision === "BLOCK") {
  validationReason = verdict.reason_code;
}

// 6. Return
return {
  json: {
    userMessage,
    sessionId,
    llmOutput,

    validationPassed: !validationFailed,
    validationFailed,
    validationReason,

    decision: validStructure
      ? verdict.decision
      : "BLOCK",

    riskLevel: validStructure
      ? verdict.risk_level
      : "HIGH",

    reasonCode: validStructure
      ? verdict.reason_code
      : "INVALID_VALIDATOR_OUTPUT",

    explanation: validStructure
      ? verdict.explanation
      : "Invalid validator response",

    guardrailStage: "SEMANTIC_INPUT_VALIDATION",
    project: "CPIA",
    environment: "demo_only"
  }
};

const extractedItems = $input.all();

const driveItems = $('02_GDrive_Search_Protocols').all();

if (extractedItems.length !== driveItems.length) {
  throw new Error(
    'PDF count does not match Google Drive file count.'
  );
}

return extractedItems.map((item, index) => {

  const file = driveItems[index].json;

  const text = item.json.text || '';

  if (!text.trim()) {
    throw new Error(`Empty PDF text: ${file.name}`);
  }

  return {
    json: {
      text: text,

      document_id: file.id,
      document_title: file.name,

      source_type: 'google_drive',
      source_file_id: file.id,

      source_url:
        file.webViewLink ||
        `https://drive.google.com/file/d/${file.id}/view`,

      mime_type: 'application/pdf',

      page_count: item.json.numpages || null,

      document_version: 'unverified',
      approval_status: 'demo_only',

      ingestion_status: 'prepared'
    }
  };
});

const answer = $json.output;

const userMessage =
  $('Validate Output').first().json.userMessage;

const sessionId =
  $('Validate Output').first().json.sessionId;

const answerText =
  typeof answer === 'string'
    ? answer
    : JSON.stringify(answer ?? '');

return {
  json: {
    userMessage,
    sessionId,
    agentOutput: answerText,
    outputEmpty: !answerText.trim(),
    guardrailStage: 'OUTPUT_PREPARATION',
    project: 'CPIA',
    environment: 'demo_only'
  }
};

const input = $input.item.json;

// 1. Get AI Agent response
let text = String(
  input.agentOutput ??
  input.output ??
  input.formattedResponse ??
  ''
);

// 2. Normalize line endings
text = text.replace(/\r\n?/g, '\n');

// 3. Convert Markdown formatting to plain text
text = text
  .replace(/\*\*(.*?)\*\*/gs, '$1')
  .replace(/__(.*?)__/gs, '$1')
  .replace(/`([^`]+)`/g, '$1')
  .replace(/\[([^\]]+)\]\((https?:\/\/[^)\s]+)\)/g, '$1 ($2)')
  .replace(/^#{1,6}\s+/gm, '')
  .replace(/(?<!\*)\*([^*\n]+)\*(?!\*)/g, '$1');

// 4. Extract document references before removing links
const documentNames = [];
const documentRegex = /[\w][\w\s().-]*?\.pdf\b/gi;

for (const match of text.matchAll(documentRegex)) {
  let name = match[0]
    .replace(/^(?:Document|Source|Reference)\s*:\s*/i, '')
    .replace(/^\s*[-•]\s*/, '')
    .trim();

  if (
    name &&
    !documentNames.some(
      existing => existing.toLowerCase() === name.toLowerCase()
    )
  ) {
    documentNames.push(name);
  }
}

// 5. Remove Google Drive links
text = text
  .replace(
    /https?:\/\/drive\.google\.com\/[^\s,)]+/gi,
    ''
  )
  .replace(/^\s*[-•]?\s*URL:\s*$/gmi, '');

// 6. Remove previously generated Source Reference blocks
text = text.replace(
  /(?:^|\n)\s*Source Reference:\s*\n\s*Document:[\s\S]*?(?=\n\s*(?:Source:|Note:|Disclaimer:|For demonstration purposes only\.)|$)/gi,
  '\n'
);

// 7. Remove duplicate Source sections
text = text.replace(
  /(?:^|\n)\s*Source:\s*\n\s*[-•]?\s*Document:[\s\S]*?(?=\n\s*(?:Note:|Disclaimer:|For demonstration purposes only\.)|$)/gi,
  '\n'
);

// 8. Remove standalone source metadata lines
text = text
  .replace(/^\s*Document Status:.*$/gmi, '')
  .replace(/^\s*[-•]?\s*Document:.*\.pdf\s*$/gmi, '')
  .replace(/^\s*[-•]?\s*URL:.*$/gmi, '');

// 9. Remove existing demo disclaimers
text = text.replace(
  /For demonstration purposes only\.\s*Documents are unverified and must not be used for clinical decisions\./gi,
  ''
);

text = text.replace(
  /Note:\s*All retrieved documents are unverified demo materials and should not be used for clinical decision-making\./gi,
  ''
);

// 10. Clean up formatting
text = text
  .replace(/\(\s*\)/g, '')
  .replace(/\s+,/g, ',')
  .replace(/[ \t]+\n/g, '\n')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

// 11. Safe fallback for empty responses
if (!text) {
  text = 'No verified response is available.';
}

// 12. Add one source section
if (documentNames.length > 0) {
  text += '\n\nSource Reference:\n';

  text += documentNames
    .map(name => 'Document: ' + name)
    .join('\n');

  text += '\nDocument Status: Unverified — Demo Only';
}

// 13. Add one disclaimer
const disclaimer =
  'For demonstration purposes only. Documents are unverified and must not be used for clinical decisions.';

text += '\n\n' + disclaimer;

// 14. Escape HTML special characters for Telegram
text = text
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');

// 15. Return formatted response
return {
  json: {
    ...input,
    formattedResponse: text,
    formattingStatus: 'COMPLETED',
    project: 'CPIA',
    environment: 'demo_only'
  }
};
